        apply_test(8'h7F, 8'h7F); // 127 + 127 = 254 -> -2 (Overflow)
        apply_test(8'h80, 8'h80); // -128 + -128 = -256 -> 0 (Overflow: max negative + max negative)
        apply_test(8'h81, 8'hFF); // -127 + -1 = -128 (No overflow)
        apply_test(8'h50, 8'h30); // 80 + 48 = 128 (Overflow)
        apply_test(8'h50, 8'hB0); // 80 + (-80) = 0 (No overflow)
        apply_test(8'h00, 8'h00); // 0 + 0 = 0
        apply_test(8'hFF, 8'h01); // -1 + 1 = 0

